const map=new Map([...pairs,...descriptions,...Object.entries(extraEnglish)]);
const words=new Map([['leche','milk'],['Gluten','Gluten'],['huevo','egg'],['pescado','fish'],['crustáceos','crustaceans'],['Leche','Milk'],['Huevo','Egg'],['Pescado','Fish'],['Crustáceos','Crustaceans'],['Frutos secos','Tree nuts'],['frutos secos','tree nuts'],['Sulfitos','Sulphites'],['sulfitos','sulphites'],['Mostaza','Mustard'],['mostaza','mustard'],['Soja','Soy'],['Apio','Celery'],['Moluscos','Molluscs'],['Sésamo','Sesame'],['Sin alérgenos declarados','No declared allergens']]);
function translate(s){const trim=s.trim();if(map.has(trim))return s.replace(trim,map.get(trim));let out=s;for(const [es,en]of [...descriptions,...pairs,...Object.entries(extraEnglish)].filter(([a])=>a.length>20).sort((a,b)=>b[0].length-a[0].length))out=out.replaceAll(es,en);for(const [es,en]of words)out=out.replaceAll(es,en);return out;}
export function translatePage(root=document.body){if(state.lang!=='en')return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement?.closest('script,style,textarea')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;const changes=[];while(node=walker.nextNode()){const value=translate(node.nodeValue);if(value!==node.nodeValue)changes.push([node,value]);}for(const [n,v]of changes)n.nodeValue=v;root.querySelectorAll?.('[placeholder],[aria-label]').forEach(el=>{for(const attr of ['placeholder','aria-label']){const v=el.getAttribute(attr);if(v){const translated=translate(v);if(v!==translated)el.setAttribute(attr,translated);}}});}
export function watchTranslations(){const observer=new MutationObserver(()=>{if(state.lang!=='en')return;observer.disconnect();translatePage();observer.observe(document.body,{childList:true,subtree:true});});observer.observe(document.body,{childList:true,subtree:true});}

